import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.YKbyQ3zk.js";const u=JSON.parse('{"title":"Passkeys","description":"","frontmatter":{},"headers":[],"relativePath":"passkeys.md","filePath":"passkeys.md"}'),o={name:"passkeys.md"};function n(r,e,h,d,l,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="passkeys" tabindex="-1">Passkeys <a class="header-anchor" href="#passkeys" aria-label="Permalink to &quot;Passkeys&quot;">​</a></h1><p>This page is for a developer turning on passkeys in an app that uses <code>@evo-auth/react</code>. A passkey lets a signed-in user sign in later with their fingerprint, face or screen lock (Windows Hello, iCloud Keychain, Google Password Manager or a security key) instead of a provider, and confirm their identity with it before a sensitive action.</p><p>With passkeys on, a signed-in user adds a passkey from their profile. With <a href="#signing-up-with-a-passkey"><code>passkeys.signUp</code></a> on as well, a new person can also sign up with an email address and a passkey and no password.</p><h2 id="turning-them-on" tabindex="-1">Turning them on <a class="header-anchor" href="#turning-them-on" aria-label="Permalink to &quot;Turning them on&quot;">​</a></h2><p>Set <a href="./reference/configuration.html#passkeysenabled"><code>passkeys.enabled</code></a> to <code>true</code> in the server config:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;">export</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> const</span><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;"> authConfig </span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">=</span><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;"> validateConfig</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">({</span></span>
<span class="line"><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;">  publicUrl</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#17723F;--shiki-dark:#7FD6A4;"> &quot;https://example.com/auth&quot;</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">,</span></span>
<span class="line"><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;">  providers</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">,</span></span>
<span class="line"><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;">  passkeys</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;"> {</span><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;"> enabled</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> true</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;"> },</span></span>
<span class="line"><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">});</span></span></code></pre></div><p><code>publicConfig</code> then carries <code>passkeys: true</code>, and the components show passkeys with no change to your React code. Both examples in this repository run with passkeys on.</p><p><strong><code>rpId</code>.</strong> A passkey is bound to its relying party id, a host name. Leave <a href="./reference/configuration.html#passkeysrpid"><code>passkeys.rpId</code></a> out and it is <code>publicUrl</code>&#39;s host name, which is right for almost every app. Set it only when several hosts under one parent domain must share passkeys, and then to that parent: for a <code>publicUrl</code> at <code>https://auth.example.com/auth</code>, <code>rpId: &quot;example.com&quot;</code> lets the same passkeys work on <code>app.example.com</code>. At start-up it must equal <code>publicUrl</code>&#39;s host name or be a parent domain of it with at least two labels, and it cannot be set when the host is an IP address. There is no public-suffix check, so a value such as <code>co.uk</code> passes start-up; it still fails safe, because the browser refuses any ceremony whose <code>rpId</code> is not the page&#39;s host or a registrable parent of it, and the user sees a refusal line. Changing <code>rpId</code> later makes every passkey already added unusable. Browsers accept <code>localhost</code> over plain http, which is how the examples run.</p><p>With passkeys off, nothing on any screen changes and the passkey routes do not exist.</p><h2 id="trying-it" tabindex="-1">Trying it <a class="header-anchor" href="#trying-it" aria-label="Permalink to &quot;Trying it&quot;">​</a></h2><p>In either example (<code>examples/tanstack-convex</code> or <code>examples/tanstack-server</code>, each with its own README steps), sign in with GitHub, open Profile and choose &quot;Add a passkey&quot;. The browser asks you to confirm with GitHub first if your last confirmation is not recent, then to name the passkey, then shows its own prompt (Windows Hello, Touch ID, a phone or a security key). Sign out, and &quot;Sign in with a passkey&quot; on the sign-in page signs you back in with the passkey alone.</p><h2 id="signing-up-with-a-passkey" tabindex="-1">Signing up with a passkey <a class="header-anchor" href="#signing-up-with-a-passkey" aria-label="Permalink to &quot;Signing up with a passkey&quot;">​</a></h2><p>Set <a href="./reference/configuration.html#passkeyssignup"><code>passkeys.signUp</code></a> to <code>true</code> and a new person can make an account from an email address and a passkey. The address is proved first, by a code or a link sent to it, and the account exists only once the passkey is made.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;">export</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> const</span><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;"> authConfig </span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">=</span><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;"> validateConfig</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">({</span></span>
<span class="line"><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;">  publicUrl</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#17723F;--shiki-dark:#7FD6A4;"> &quot;https://example.com/auth&quot;</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">,</span></span>
<span class="line"><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;">  providers</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">,</span></span>
<span class="line"><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;">  email</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;"> {</span><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;"> sender </span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">},</span></span>
<span class="line"><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;">  emailAuth</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;"> {</span><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;"> code</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> true</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">,</span><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;"> link</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> true</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">,</span><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;"> signUp</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> true</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;"> },</span></span>
<span class="line"><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;">  passkeys</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;"> {</span><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;"> enabled</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> true</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">,</span><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;"> signUp</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> true</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;"> },</span></span>
<span class="line"><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">});</span></span></code></pre></div><p><code>validateConfig</code> refuses <code>passkeys.signUp</code> unless <code>passkeys.enabled</code> and <code>emailAuth.signUp</code> are on, <code>email.sender</code> is set, and at least one of <code>emailAuth.code</code>, <code>emailAuth.link</code> and <code>emailAuth.password</code> is on, so a person who signs up with a passkey always has a way back in by email. On Convex, <code>registerRoutes</code> needs its <code>emailJob</code> while it is on, as it does for the email methods (<a href="./convex.html#sending-email">Convex</a>). <code>publicConfig</code> carries <code>passkeySignUp: true</code>.</p><p><strong>What the person sees.</strong> <code>SignUp</code>, and the sign-in card&#39;s &quot;Create an account&quot;, show while <code>(emailAuth.password || passkeySignUp) &amp;&amp; emailAuth.signUp</code>. With <code>passkeySignUp</code> on, the card opens on the passkey:</p><ol><li>The address and &quot;Continue with a passkey&quot;. With passwords on too, &quot;Use a password instead&quot; opens the password form, and the password form offers &quot;Use a passkey instead&quot;; the address is kept either way.</li><li>&quot;Check your email&quot;: the six-digit code, with &quot;Send a new code&quot; and &quot;Use a different address&quot;. The email is the <code>sign_up</code> message. While <code>emailAuth.link</code> is on it also holds a link; opened in the browser that asked, the sign-in page shows &quot;Finish creating your account&quot; and Continue goes on to the next step.</li><li>&quot;Create your passkey&quot;: a name, filled with &quot;Passkey on {system}&quot;, then &quot;Create passkey&quot; and the browser&#39;s own prompt. The name is checked before anything is sent, and fresh options are fetched right before every prompt, so the step does not run out while the person reads it.</li><li>The person is signed in and goes to the redirect. There is no extra screen.</li></ol><p>An address that already has an account gets the <code>existing_account_notice</code> email instead of a code, and the card answers exactly as for a new address. A closed prompt goes back to step 3 quietly. The other refusals each have their own line: a wrong or expired code, too many tries, a wait after too many requests, an address that got an account meanwhile (&quot;Sign in instead&quot;), and a sign-up that has expired (&quot;Start again&quot;).</p><p><strong>Routes.</strong> Three POST routes under <code>{basePath}/passkeys/sign-up</code> exist only while the setting is on; otherwise they answer the generic 404.</p><table tabindex="0"><thead><tr><th>Route</th><th>Body</th><th>Answer</th></tr></thead><tbody><tr><td><code>/start</code></td><td><code>{ email }</code></td><td><code>200 { sent: true }</code> for every address the server takes, with the email cookie that ties the code and the link to this browser. <code>400 email_address</code>, or <code>429</code> with <code>Retry-After</code>.</td></tr><tr><td><code>/options</code></td><td><code>{ code }</code>, <code>{ token }</code> (a link&#39;s) or <code>{}</code></td><td><code>200</code> with the registration options. The first code or link proves the address; after that <code>{}</code> gives fresh options for 5 minutes, and a code or link sent again counts as <code>{}</code>. <code>400</code> with <code>wrong_code</code>, <code>too_many_attempts</code>, <code>challenge_expired</code> or <code>email_other_browser</code> (a link opened in another browser, which counts nothing), or the generic 404 without the email cookie.</td></tr><tr><td><code>/verify</code></td><td><code>{ name, credential }</code></td><td><code>200 { accessToken, expiresAt }</code> with the session cookies: the user, the verified email account and the passkey are made together, and the session starts at once, with no second step. <code>400</code> with <code>passkey_name</code>, <code>passkey_failed</code>, <code>address_taken</code> or <code>passkey_exists</code>, or <code>challenge_expired</code>.</td></tr></tbody></table><p>The registration options carry the account&#39;s user handle, 16 random bytes as 22 base64url characters, not the user&#39;s id; a passkey added later from the profile carries the same handle. The rules behind each step are in <a href="./security-model.html#passkey-sign-up">the security model</a>.</p><p><strong>Limits and events.</strong> <code>/start</code> counts <code>email_sign_up</code> for the client address first, then <code>email_send</code> and <code>email_recipient</code>, as a password sign-up does. A sign-up allows 5 wrong codes; a failed registration counts toward the same 5. <code>/verify</code> records <code>sign_up</code>, <code>passkey_added</code> and <code>sign_in</code>, and runs <code>onUserCreated</code>; <code>user.created</code> is the only webhook event. <code>/start</code> and <code>/options</code> record nothing.</p><h2 id="at-a-shared-sign-in-server" tabindex="-1">At a shared sign-in server <a class="header-anchor" href="#at-a-shared-sign-in-server" aria-label="Permalink to &quot;At a shared sign-in server&quot;">​</a></h2><p>With passkeys on at a hub, its chooser counts the passkey as a way in and links to the hub&#39;s own sign-in page, so a person whose only way in is a passkey can sign in to an app through the hub, and confirm their identity when an app asks for a fresh sign-in. The apps themselves need nothing new. See <a href="./hub.html">Passkeys at the hub</a>.</p><h2 id="what-the-user-sees" tabindex="-1">What the user sees <a class="header-anchor" href="#what-the-user-sees" aria-label="Permalink to &quot;What the user sees&quot;">​</a></h2><ul><li><strong><code>SignIn</code></strong> ends its list with &quot;Sign in with a passkey&quot;, when the browser can use one. While the browser shows its own prompt, the button waits and the provider buttons are held. After a successful sign-in the browser goes to the <code>redirect</code> prop, or to the page the user is on, exactly as after a provider sign-in, and the provider reads the new session there.</li><li><strong>Autofill on the email field.</strong> Clicking the sign-in card&#39;s email field can show the person&#39;s saved passkeys in the browser&#39;s own autofill list; picking one signs them in with no button and no typing. See <a href="#autofill">Autofill</a>.</li><li><strong><code>UserProfile</code></strong> has a Passkeys section. Each passkey shows its name, when it was added, when it was last used, and &quot;Synced&quot; or &quot;This device only&quot;. The user can add, rename and remove passkeys.</li><li><strong>Adding</strong> asks for a recent confirmation of identity first: &quot;Use a passkey&quot; when the user already has one this browser can use, otherwise the provider. Then a row names the new passkey, filled with &quot;Passkey on Windows&quot; (or the system the browser reports), or &quot;Passkey&quot; when the system cannot be read, and the user can change it before the browser&#39;s prompt.</li><li><strong>Every confirmed action</strong> in the profile (deleting the account, connecting or disconnecting an account, adding or removing a passkey) and on the admin page (ban, unban, delete) offers &quot;Use a passkey&quot; beside the provider when the user has a passkey this browser can use. A passkey confirms in place, with no trip to the provider.</li><li><strong><code>AdminPanel</code></strong> lists a user&#39;s passkeys on their page, each with a remove control behind a confirmation. The removal is recorded with the admin as the actor. Only the user can add or rename their passkeys.</li></ul><p>The last way to sign in, accounts and passkeys counted together, cannot be removed, by the user or by an admin. An admin who wants to stop a user signing in bans or deletes them instead.</p><p>Removing a passkey ends the user&#39;s other sessions: the user&#39;s own removal signs out every other device, and its confirmation says so; an admin&#39;s removal signs the user out everywhere. See <a href="./security-model.html#revocation">Revocation</a>.</p><h2 id="autofill" tabindex="-1">Autofill <a class="header-anchor" href="#autofill" aria-label="Permalink to &quot;Autofill&quot;">​</a></h2><p>Autofill has no setting. It runs on <code>SignIn</code>&#39;s email field whenever <code>publicConfig.passkeys</code> is <code>true</code>, the card shows that field (an email sign-in method is on: <code>emailAuth.code</code>, <code>emailAuth.link</code> or <code>emailAuth.password</code>) and the browser answers <code>PublicKeyCredential.isConditionalMediationAvailable()</code> with <code>true</code>. Nothing is added to the card: the field&#39;s <code>autocomplete</code> is <code>&quot;email webauthn&quot;</code>, and the browser draws the list.</p><ul><li><strong>The request.</strong> When the field appears, the card posts <code>POST {basePath}/passkeys/signin/options</code> with <code>{ &quot;conditional&quot;: true }</code> and asks the browser with <code>navigator.credentials.get({ mediation: &quot;conditional&quot; })</code>. The browser shows nothing until the person clicks the field, and then offers the site&#39;s passkeys beside any saved addresses. Picking one posts it to <code>/passkeys/signin/verify</code>, with the same limits and refusals as the button, and lands where the button lands.</li><li><strong>A pending second step stays as it is.</strong> For <code>{ &quot;conditional&quot;: true }</code> the options route always answers the ordinary sign-in options and leaves a pending second step&#39;s cookie alone, so reloading the sign-in page during a second step, or opening it in another tab, cancels nothing. See <a href="./security-model.html#two-step-sign-in">Two-step sign-in in the security model</a>.</li><li><strong>One request at a time.</strong> &quot;Sign in with a passkey&quot;, a provider&#39;s button, the address&#39;s Continue and &quot;Create an account&quot; each stop autofill before they send anything. While the card shows a second step, or any step that replaces the email field, autofill is not running.</li><li><strong>Keeping it fresh.</strong> The challenge lasts 120 seconds, so the card asks again every 110 seconds, but only while the tab is visible and the field does not have focus, so an open list is never closed under the person. It also asks again when the tab becomes visible, when the field gains focus with a request older than about 90 seconds, and after a refusal. Each refresh is one options request; it writes nothing and counts no limit.</li><li><strong>A refusal</strong> shows &quot;Couldn&#39;t sign you in with a passkey. Try again, or use another way to sign in.&quot;, and the list is offered again.</li><li><strong>Where it is not.</strong> The sign-up card has nothing to fill. The shared sign-in server&#39;s chooser page has no script, so it has no autofill; the hub&#39;s own sign-in page, which is <code>SignIn</code>, has it.</li><li><strong>The browser decides.</strong> Whether a browser offers passkeys in a field marked <code>&quot;email webauthn&quot;</code>, and how its list looks, is the browser&#39;s. A browser that answers <code>false</code>, or has no <code>isConditionalMediationAvailable</code>, shows the card exactly as before.</li></ul><h2 id="when-the-browsers-prompt-does-not-finish" tabindex="-1">When the browser&#39;s prompt does not finish <a class="header-anchor" href="#when-the-browsers-prompt-does-not-finish" aria-label="Permalink to &quot;When the browser&#39;s prompt does not finish&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What happened</th><th>What the user sees</th></tr></thead><tbody><tr><td>The user closed the prompt, or it timed out (<code>NotAllowedError</code>)</td><td>The card or dialog goes back to how it was. Nothing more is sent.</td></tr><tr><td>The device already holds a passkey for this account (<code>InvalidStateError</code> while adding)</td><td>&quot;This device already has a passkey for your account.&quot;</td></tr><tr><td>Any other browser error, such as <code>SecurityError</code> from a wrong <code>rpId</code></td><td>A refusal line.</td></tr><tr><td>The server refused the completed ceremony</td><td>A refusal line; a bad name, a passkey already registered and the limit of 20 each get their own sentence.</td></tr></tbody></table><h2 id="your-own-screens" tabindex="-1">Your own screens <a class="header-anchor" href="#your-own-screens" aria-label="Permalink to &quot;Your own screens&quot;">​</a></h2><p><a href="./react.html#usepasskeys"><code>usePasskeys()</code></a> gives the same list and actions for a screen of your own. The package converts every byte string by hand and never calls <code>PublicKeyCredential.parseCreationOptionsFromJSON</code>, <code>parseRequestOptionsFromJSON</code> or <code>toJSON</code>, which WebKit lacks.</p><h2 id="what-the-tests-prove-and-what-only-a-real-device-does" tabindex="-1">What the tests prove, and what only a real device does <a class="header-anchor" href="#what-the-tests-prove-and-what-only-a-real-device-does" aria-label="Permalink to &quot;What the tests prove, and what only a real device does&quot;">​</a></h2><p>The three-browser suite (<code>tests/acceptance/app/passkeys.spec.ts</code>, <code>hub-passkeys.spec.ts</code> and, for signing up, <code>passkey-sign-up.spec.ts</code> and <code>server-passkey-sign-up.spec.ts</code>) runs the examples in headless Chromium, Firefox and WebKit with Playwright&#39;s virtual authenticator, which stands in for <code>navigator.credentials</code> in the page. It proves, in all three:</p><ul><li>adding a passkey from the profile, signing out, and signing in with the passkey alone;</li><li>confirming identity with it before removing a passkey and before deleting the account; renaming; removing, after which the server refuses that passkey at sign-in;</li><li>refusal of a passkey made for another <code>rpId</code>, of a signature counter that went backwards, and of a banned or deleted user;</li><li>at a hub, a person whose only way in is a passkey signing in to an app through the chooser, and confirming their identity for an app with a fresh <code>auth_time</code>, or cancelling and the app receiving <code>login_required</code>;</li><li>signing up with an address and a passkey on both examples, signing back in with it, a second passkey from another browser joining the same account, the notice to an address that already has one, a closed prompt, and the emailed link in the browser that asked and in another;</li><li>autofill (<code>passkey-autofill.spec.ts</code> and <code>server-passkey-autofill.spec.ts</code>): a passkey made at sign-up signing in when the sign-in page opens, the button still signing in beside autofill, and a second step pending in another tab left as it was.</li></ul><p>The virtual authenticator always makes ES256 keys, always reports the user present and verified, never reports a backed-up (synced) passkey, and shows no account chooser. It answers a conditional request at once with the first passkey it holds, with no list and no person, and ignores the abort signal, so the suite proves autofill&#39;s requests and what follows a pick, not the browser&#39;s list or that stopping autofill closes it. The hook&#39;s rules for starting, refreshing, restarting and stopping are proved against a stand-in for <code>navigator.credentials</code> with a test clock. So these need a real device: Windows Hello, iCloud Keychain, Google Password Manager and security keys, signing in with a phone by QR code, the real user-verification prompts, the browser&#39;s autofill list and its closing when autofill stops, an RS256 passkey (Windows Hello on many machines; the server&#39;s RS256 check is tested in core), the &quot;Synced&quot; label, and the refusal of a response without user verification (tested in core).</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>The server enforces its own rules; see <a href="./security-model.html#passkeys">Passkeys in the security model</a> for the checks, the counter rule and what an attacker would need.</li><li>Attestation (knowing which make of authenticator the user has) is not offered.</li><li>Someone at an unattended browser on the &quot;Create your passkey&quot; step could finish the sign-up with their own passkey, as with any sign-up left open. That step lives 5 minutes after the address is proved.</li><li>Removing a passkey here does not remove it from the user&#39;s device or password manager, which may still list it until the user deletes it there.</li></ul>`,41)])])}const k=s(o,[["render",n]]);export{u as __pageData,k as default};
